import { Newsletter } from "march/landing"

// bir kitapçının bülteni: sunucu 600 ms sonra yanıt verir (bu sırada düğme dönen simgesini gösterir);
// zaten kayıtlı adres hata olarak okunur
const kayitli = new Set(["okur@ornek.com"])
const kaydet = (email: string) => new Promise((ok, no) => setTimeout(() => {
  if (kayitli.has(email)) no(new Error("Bu adres zaten bültende."))
  else { kayitli.add(email); ok(true) }
}, 600))

export function BookstoreBulletin() {
  return <Newsletter title="Haftanın kitapları" lead="Her cuma beş yeni kitap, bir de söyleşi daveti."
    placeholder="okur@ornek.com" button="Abone ol" note="Ayrılmak tek tık. Adresini kimseyle paylaşmayız."
    done="Teşekkürler! İlk bülten cuma sabahı gelecek." onSubmit={kaydet} />
}

import { Newsletter } from "march/landing"
import { Toggle, Card } from "march/ui"
import { heart, Icon } from "march/icons"

// Newsletter'ın bütün özellikleri bir arada: gönderme (onSubmit: başarı ya da hata), başlık, açıklama, yer tutucu,
// düğme metni, not, teşekkür satırı, düzen, kendi metinler (labels), onay simgesi, hareket ve sınıf
export function NewsletterLab() {
  let $stacked = false
  let $fail = false
  let $motion = false
  let $ownIcon = false
  let $count = 0
  return <div sx={{ flex: "col", gap: 3 }}>
    <Card>
      <div sx={{ flex: ["row", "wrap"], gap: 3 }}>
        <Toggle label="Alt alta" bind:value={$stacked} />
        <Toggle label="Sunucu hatası" bind:value={$fail} />
        <Toggle label="Hareket" bind:value={$motion} />
        <Toggle label="Kalp simgesi" bind:value={$ownIcon} />
      </div>
      <p sx={{ color: "muted" }}>{$count} abone</p>
    </Card>
    {() => {
      // sinyaller burada okunur: değişince form yeniden çizilir
      const stacked = $stacked, fail = $fail, motion = $motion, ownIcon = $ownIcon
      return <Newsletter class="lab-nl" layout={stacked ? "stacked" : "inline"} motion={motion}
        title="Haberdar ol" lead="Ayda bir e-posta." placeholder="adın@ornek.com" button="Kaydol"
        note="İstediğin an ayrılabilirsin." done="Görüşmek üzere!"
        doneIcon={ownIcon ? <Icon of={heart} /> as Node : true}
        labels={{ email: "E-posta adresin", invalid: "Geçerli bir adres yaz.", error: "Bir sorun çıktı." }}
        onSubmit={() => { if (fail) throw new Error(""); $count++ }} />
    }}
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { NewsletterLab } from "./NewsletterLab.tsx"

// NewsletterLab'in testleri: kaydedince Testler sekmesinde çalışır
test("başlık, açıklama, not, yer tutucu ve düğme metni", () => {
  const s = renderTest(() => <NewsletterLab />)
  expect(s.find("Haberdar ol")).not.toBe(null)
  expect(s.find("İstediğin an ayrılabilirsin.")).not.toBe(null)
  expect(s.get('.lab-nl input[type="email"]')?.getAttribute("placeholder")).toBe("adın@ornek.com")
  expect(s.find("Kaydol")).not.toBe(null)
})

test("geçersiz adres: kendi hata metni okunur", async () => {
  const s = renderTest(() => <NewsletterLab />)
  await s.type("E-posta adresin", "abc")
  await s.click("Kaydol")
  await s.wait(() => s.sees("Geçerli bir adres yaz."))
  expect(s.sees("Geçerli bir adres yaz.")).toBeTruthy()
})

test("geçerli adres: teşekkür satırı ve sayaç", async () => {
  const s = renderTest(() => <NewsletterLab />)
  await s.type("E-posta adresin", "ali@ornek.com")
  await s.click("Kaydol")
  await s.wait(() => s.sees("Görüşmek üzere!"))
  expect(s.get('.lab-nl [role="status"]')?.textContent).toContain("Görüşmek üzere!")
  expect(s.find("1 abone")).not.toBe(null)
})

test("sunucu hatası: genel hata metni, form yerinde kalır", async () => {
  const s = renderTest(() => <NewsletterLab />)
  await s.click("Sunucu hatası")
  await s.type("E-posta adresin", "ali@ornek.com")
  await s.click("Kaydol")
  await s.wait(() => s.sees("Bir sorun çıktı."))
  expect(s.get(".lab-nl form")).not.toBe(null)
})
